-- Actualiza el copy publicado de monitores y mobiliario.
-- El seed 20260927020100 inserta con ON CONFLICT DO NOTHING, así que las filas
-- ya publicadas no recogen el texto de src/data/familia-seo.ts.
-- relatedSlugs sigue saliendo del código (mezclarFamilia).

UPDATE public.landings AS landing
SET contenido_es = nuevo.contenido_es,
    contenido_en = nuevo.contenido_en,
    version = landing.version + 1,
    publicado_at = NOW()
FROM (VALUES
  ('mobiliario', $ime_seo${"name":"Cama hospitalaria y cama eléctrica","title":"Cama hospitalaria eléctrica para clínicas de Colombia | I-ME","description":"Cama hospitalaria y cama eléctrica hospitalaria para clínicas en Colombia. Compare B-1000 Pro, B-2000 y B-2000 Plus y cotice la configuración del servicio.","intro":"La cama hospitalaria se define por el servicio, el personal y el recorrido del área. La cama eléctrica hospitalaria cambia de posición con motores; la manual, con manivelas. Las dos se cotizan por referencia, no como un mueble genérico.","body":["En el catálogo activo están la cama eléctrica Advanced B-1000 Pro, la B-2000 Plus y la Saikang V6K, y la cama hospitalaria manual Advanced B-2000. Las funciones y medidas de cada una están en su página; no se trasladan de un modelo a otro.","Esta familia también reúne camillas, carros y mesas del mismo entorno clínico. Las camillas de traslado están en emergencias, y las camas obstétricas en neonatología. Para cotizar, indique el espacio útil, las puertas y el uso previsto."],"faq":[{"q":"¿Qué diferencia una cama eléctrica hospitalaria de una manual?","a":"La eléctrica ajusta la posición con motores y la manual con manivelas. Cuál conviene depende del servicio, del personal y del espacio. La configuración de cada referencia se confirma en su página y en la cotización."},{"q":"¿Qué medidas debo enviar?","a":"Espacio útil, puertas, ascensores, recorridos y restricciones del área, además del uso previsto."}]}$ime_seo$::jsonb, $ime_seo${"name":"Hospital beds in Colombia","title":"Electric hospital bed Colombia for clinics and wards | I-ME","description":"Electric and manual hospital beds for wards and ICU in Colombia. Compare B-1000 Pro, B-2000 and B-2000 Plus, then request a quote for your service.","intro":"A hospital bed in Colombia is chosen for the ward, the staff and the route through the building. An electric hospital bed changes position with motors; a manual bed uses cranks. Both are quoted by reference, not as generic furniture.","body":["Active electric hospital beds include the Advanced B-1000 Pro, the B-2000 Plus and the Saikang V6K. The Advanced B-2000 is a manual hospital bed. Functions and dimensions stay on each product page; they are not copied from one model to another.","The same family also lists stretchers, carts and tables used on those wards. Transfer stretchers are in the emergency family, and obstetric beds are with neonatology. When you request a quote, send usable space, doors and the intended service."],"faq":[{"q":"How does an electric hospital bed differ from a manual one?","a":"An electric bed changes position with motors; a manual bed uses cranks. Which one fits depends on the service, the staff and the room. Each reference’s configuration is confirmed on its page and in the quote."},{"q":"Which measurements should I send?","a":"Usable space, doors, elevators, routes and area restrictions, plus intended use."}]}$ime_seo$::jsonb),
  ('monitores', $ime_seo${"name":"Monitores de paciente para hospitales","title":"Monitores de paciente para UCI y hospitales | I-ME","description":"Monitores de paciente multiparamétricos para UCI, urgencias y hospitalización en Colombia. I-ME orienta parámetros, modularidad y soporte antes de cotizar.","intro":"Un monitor de paciente se elige por el servicio que lo va a usar — observación, urgencias, transporte o UCI — y no solo por el tamaño de la pantalla.","body":["En hospitales de Colombia el punto de partida suele ser ECG, oximetría de pulso y presión no invasiva, y se suman capnografía o presión invasiva solo si ese servicio las usa. I-ME revisa alarmas, central y transporte antes de cotizar una referencia.","Las preguntas sobre Biolight S12 y P15 están en la guía de monitores UCI. En el catálogo activo está el monitor de paciente Advanced PM-2000A PRO, junto con la familia de cardiología y la de ventiladores. La documentación y el soporte se confirman por referencia."],"faq":[{"q":"¿Qué diferencia un monitor básico de uno de UCI?","a":"La criticidad del servicio: parámetros expandibles, alarmas, autonomía y capacidad de central. Lo básico cubre observación; UCI suele exigir más modularidad y continuidad."},{"q":"¿I-ME instala y capacita?","a":"Sí, el alcance de instalación y capacitación se acuerda en la cotización según sede y cantidad de puntos."},{"q":"¿Tienen el monitor Biolight S12?","a":"La guía de monitores Biolight para UCI reúne las preguntas sobre S12 y P15. La disponibilidad se confirma al cotizar. El catálogo activo incluye monitores como el PM-2000A PRO."}]}$ime_seo$::jsonb, $ime_seo${"name":"Patient monitors for hospitals","title":"Patient monitors for hospitals and ICU in Colombia | I-ME","description":"Compare multiparameter patient monitors for ICU, emergency and wards in Colombia. I-ME matches parameters, modularity and support before a quote.","intro":"A patient monitor is chosen for the service that will use it — observation, emergency, transport or ICU — not by screen size alone.","body":["Colombian hospitals usually start with ECG, pulse oximetry and non-invasive blood pressure, and add capnography or invasive pressure only when that service uses them. I-ME reviews alarms, central station and transport before quoting a reference.","Biolight S12 and P15 questions are covered in the ICU monitor guide. The active catalog includes the Advanced PM-2000A PRO patient monitor, plus the cardiology and ventilator families. Documentation and support are confirmed per reference."],"faq":[{"q":"What separates a basic monitor from an ICU monitor?","a":"Service criticality: expandable parameters, alarms, autonomy and central-station readiness. Basic units fit observation; ICU usually needs modularity and continuity."},{"q":"Does I-ME install and train?","a":"Yes — installation and training scope are agreed in the quote by site and number of points."},{"q":"Do you cover the Biolight S12 monitor?","a":"The Biolight ICU monitor guide collects S12 and P15 questions. Availability is confirmed when quoting. The active catalog includes monitors such as the PM-2000A PRO."}]}$ime_seo$::jsonb)
) AS nuevo(clave, contenido_es, contenido_en)
WHERE landing.tipo = 'familia'
  AND landing.clave = nuevo.clave;

INSERT INTO public.landings_historial (landing_id, version, contenido_es, contenido_en)
SELECT id, version, contenido_es, contenido_en
FROM public.landings
WHERE tipo = 'familia'
  AND clave IN ('mobiliario', 'monitores')
ON CONFLICT (landing_id, version) DO NOTHING;
